Here's the result of running `cat -n` on a snippet of features/qr-detail/components/ContentCard.tsx
     1→import React from "react";
     2→import { View, Text, StyleSheet, Pressable, Platform } from "react-native";
     3→import { Ionicons } from "@expo/vector-icons";
     4→import { LinearGradient } from "expo-linear-gradient";
     5→import * as Clipboard from "expo-clipboard";
     6→import * as Haptics from "@/lib/haptics";
     7→import type { ParsedPaymentQr } from "@/lib/qr-analysis";
     8→import { useTheme } from "@/contexts/ThemeContext";
     9→import PaymentCard from "./PaymentCard";
    10→import type { AppColors } from "@/constants/colors";
    11→import { getQrTypeStyle } from "@/lib/config/qr-type-styles";
    12→
    13→type GradientPair = readonly [string, string];
    14→
    15→function parseWifi(content: string) {
    16→  try {
    17→    const ssid = content.match(/S:([^;]*)/)?.[1] ?? "";
    18→    const password = content.match(/P:([^;]*)/)?.[1] ?? "";
    19→    const security = content.match(/T:([^;]*)/)?.[1] ?? "WPA";
    20→    const hidden = content.includes("H:true");
    21→    if (!ssid) return null;
    22→    return { ssid, password, security, hidden };
    23→  } catch { return null; }
    24→}
    25→
    26→function parseContact(content: string) {
    27→  const r = { name: "", phone: "", email: "", org: "", url: "", title: "", note: "" };
    28→  if (content.startsWith("BEGIN:VCARD")) {
    29→    // FN (Formatted Name) preferred; fall back to structured N field
    30→    const fn = content.match(/^FN:(.+)$/m)?.[1]?.trim() ?? "";
    31→    if (fn) {
    32→      r.name = fn;
    33→    } else {
    34→      const nField = content.match(/^N:(.+)$/m)?.[1]?.trim() ?? "";
    35→      // N field is Last;First;Middle;Prefix;Suffix — reassemble to "First Last"
    36→      const [last = "", first = ""] = nField.split(";");
    37→      r.name = [first.trim(), last.trim()].filter(Boolean).join(" ");
    38→    }
    39→    // TEL — strip type parameters like ;TYPE=CELL, ;TYPE=WORK
    40→    r.phone = (content.match(/^TEL[^:\r\n]*:(.+)$/m)?.[1] ?? "").trim();
    41→    // EMAIL — strip type parameters
    42→    r.email = (content.match(/^EMAIL[^:\r\n]*:(.+)$/m)?.[1] ?? "").trim();
    43→    r.org   = (content.match(/^ORG:(.+)$/m)?.[1] ?? "").trim().split(";")[0].trim();
    44→    r.url   = (content.match(/^URL:(.+)$/m)?.[1] ?? "").trim();
    45→    r.title = (content.match(/^TITLE:(.+)$/m)?.[1] ?? "").trim();
    46→    r.note  = (content.match(/^NOTE:(.+)$/m)?.[1] ?? "").trim().slice(0, 120);
    47→  } else if (content.toLowerCase().startsWith("mecard:")) {
    48→    r.name  = content.match(/N:([^;]+)/)?.[1]?.trim() ?? "";
    49→    r.phone = content.match(/TEL:([^;]+)/)?.[1]?.trim() ?? "";
    50→    r.email = content.match(/EMAIL:([^;]+)/)?.[1]?.trim() ?? "";
    51→  }
    52→  return r;
    53→}
    54→
    55→function parseSms(content: string) {
    56→  // Handle SMSTO:phone:message format (generated by the QR registry)
    57→  const smsto = content.match(/^SMSTO:([^:]*):?(.*)?$/i);
    58→  if (smsto) {
    59→    return { to: smsto[1]?.trim() ?? "", body: smsto[2]?.trim() ?? "" };
    60→  }
    61→  // Handle sms:phone?body=message format
    62→  try {
    63→    const url = new URL(content);
    64→    const to = url.pathname.replace(/^\//, "");
    65→    const body = url.searchParams.get("body") ?? "";
    66→    return { to, body };
    67→  } catch { return { to: content.replace(/^sms[to]*:/i, "").split("?")[0], body: "" }; }
    68→}
    69→
    70→function parseWhatsApp(content: string) {
    71→  try {
    72→    const u = new URL(content.startsWith("http") ? content : `https://${content}`);
    73→    const phone = u.pathname.replace(/^\//, "").replace(/\D/g, "");
    74→    const text = u.searchParams.get("text") ?? "";
    75→    return { phone: phone ? "+" + phone : content, text };
    76→  } catch { return { phone: content, text: "" }; }
    77→}
    78→
    79→function parseEmail(content: string) {
    80→  try {
    81→    const bare = content.replace(/^mailto:/i, "");
    82→    const [addr, qs = ""] = bare.split("?");
    83→    const p = new URLSearchParams(qs);
    84→    return { email: addr || "", subject: p.get("subject") ?? "", body: p.get("body") ?? "" };
    85→  } catch { return { email: content, subject: "", body: "" }; }
    86→}
    87→
    88→function parsePhone(content: string) {
    89→  return content.replace(/^(tel:|callto:|facetime:)/i, "").trim();
    90→}
    91→
    92→function parseEvent(content: string) {
    93→  return {
    94→    summary: content.match(/SUMMARY:([^\r\n]+)/)?.[1] ?? "",
    95→    dtstart: content.match(/DTSTART[^:]*:([^\r\n]+)/)?.[1] ?? "",
    96→    dtend: content.match(/DTEND[^:]*:([^\r\n]+)/)?.[1] ?? "",
    97→    location: content.match(/LOCATION:([^\r\n]+)/)?.[1] ?? "",
    98→    description: content.match(/DESCRIPTION:([^\r\n]+)/)?.[1] ?? "",
    99→  };
   100→}
   101→
   102→function icalToDate(dt: string): Date | null {
   103→  if (!dt) return null;
   104→  try {
   105→    const y = dt.slice(0, 4), mo = dt.slice(4, 6), d = dt.slice(6, 8);
   106→    const h = dt.slice(9, 11) || "00", mi = dt.slice(11, 13) || "00";
   107→    return new Date(`${y}-${mo}-${d}T${h}:${mi}:00`);
   108→  } catch { return null; }
   109→}
   110→
   111→function formatEventDate(dt: string): string {
   112→  if (!dt) return "";
   113→  const date = icalToDate(dt);
   114→  if (!date) return dt;
   115→  return date.toLocaleDateString(undefined, { weekday: "long", year: "numeric", month: "long", day: "numeric" });
   116→}
   117→
   118→function formatEventTime(dt: string): string {
   119→  if (!dt) return "";
   120→  const date = icalToDate(dt);
   121→  if (!date) return "";
   122→  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
   123→}
   124→
   125→function isEventPast(dtend: string, dtstart: string): boolean {
   126→  const ref = dtend || dtstart;
   127→  if (!ref) return false;
   128→  const date = icalToDate(ref);
   129→  return date ? date < new Date() : false;
   130→}
   131→
   132→function parseLocation(content: string) {
   133→  const lower = content.toLowerCase();
   134→  if (lower.startsWith("geo:")) {
   135→    const afterGeo = content.slice(4);
   136→    const [coordsPart, queryPart = ""] = afterGeo.split("?");
   137→    const [lat = "", lon = ""] = coordsPart.split(",");
   138→    const label = new URLSearchParams(queryPart).get("q") || "";
   139→    return { lat: lat.trim(), lon: lon.trim(), label: label ? decodeURIComponent(label) : "" };
   140→  }
   141→  if (lower.includes("maps.google.com") || lower.includes("goo.gl/maps")) {
   142→    try {
   143→      const u = new URL(content);
   144→      const q = u.searchParams.get("q") || "";
   145→      return { lat: "", lon: "", label: q ? decodeURIComponent(q) : content };
   146→    } catch {}
   147→  }
   148→  return { lat: "", lon: "", label: content };
   149→}
   150→
   151→function parseCrypto(content: string) {
   152→  const m = content.match(/^(bitcoin|ethereum|litecoin|solana):([^?]+)(\?(.*))?$/i);
   153→  if (m) {
   154→    const coin = m[1].charAt(0).toUpperCase() + m[1].slice(1);
   155→    const address = m[2].trim();
   156→    const amount = new URLSearchParams(m[4] || "").get("amount") || "";
   157→    return { coin, address, amount };
   158→  }
   159→  return { coin: "", address: content, amount: "" };
   160→}
   161→
   162→function extractBasicPaymentInfo(content: string) {
   163→  try {
   164→    return {
   165→      vpa: content.match(/pa=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/pa=([^&\s]+)/i)![1]) : undefined,
   166→      name: content.match(/pn=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/pn=([^&\s]+)/i)![1]) : undefined,
   167→      amount: content.match(/(?:\bam|amount)=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/(?:\bam|amount)=([^&\s]+)/i)![1]) : undefined,
   168→      currency: content.match(/cu=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/cu=([^&\s]+)/i)![1]) : undefined,
   169→    };
   170→  } catch { return {}; }
   171→}
   172→
   173→// ── URL type field extractor ────────────────────────────────────────────────
   174→// For URL-based template types, pull meaningful fields back out of the URL
   175→// so ContentCard can show them as structured InfoRows instead of bare links.
   176→type UrlField = { label: string; value: string; icon: keyof typeof Ionicons.glyphMap };
   177→
   178→function extractUrlDisplayFields(contentType: string, content: string): UrlField[] {
   179→  const fields: UrlField[] = [];
   180→  try {
   181→    switch (contentType) {
   182→      case "instagram": {
   183→        const m = content.match(/instagram\.com\/([^/?#\s]+)/);
   184→        if (m?.[1] && m[1] !== "p" && m[1] !== "reel") fields.push({ label: "Profile", value: `@${m[1]}`, icon: "person-outline" });
   185→        break;
   186→      }
   187→      case "twitter": {
   188→        const m = content.match(/(?:twitter|x)\.com\/([^/?#\s]+)/);
   189→        if (m?.[1] && !["i", "intent", "home", "explore"].includes(m[1])) fields.push({ label: "Username", value: `@${m[1]}`, icon: "person-outline" });
   190→        break;
   191→      }
   192→      case "tiktok": {
   193→        const m = content.match(/tiktok\.com\/@([^/?#\s]+)/);
   194→        if (m?.[1]) fields.push({ label: "Username", value: `@${m[1]}`, icon: "person-outline" });
   195→        break;
   196→      }
   197→      case "snapchat": {
   198→        const m = content.match(/snapchat\.com\/add\/([^/?#\s]+)/);
   199→        if (m?.[1]) fields.push({ label: "Username", value: m[1], icon: "person-outline" });
   200→        break;
   201→      }
   202→      case "youtube": {
   203→        const channel = content.match(/youtube\.com\/@([^/?#\s]+)/)?.[1] ?? content.match(/youtube\.com\/channel\/([^/?#\s]+)/)?.[1] ?? content.match(/youtube\.com\/c\/([^/?#\s]+)/)?.[1];
   204→        const video = content.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([^&/?#\s]+)/)?.[1];
   205→        if (channel) fields.push({ label: "Channel", value: `@${channel}`, icon: "play-circle-outline" });
   206→        if (video)   fields.push({ label: "Video", value: video, icon: "play-outline" });
   207→        break;
   208→      }
   209→      case "spotify": {
   210→        const track    = content.match(/spotify\.com\/track\/([^/?#\s]+)/)?.[1];
   211→        const album    = content.match(/spotify\.com\/album\/([^/?#\s]+)/)?.[1];
   212→        const playlist = content.match(/spotify\.com\/playlist\/([^/?#\s]+)/)?.[1];
   213→        const artist   = content.match(/spotify\.com\/artist\/([^/?#\s]+)/)?.[1];
   214→        if (track)    fields.push({ label: "Track", value: track, icon: "musical-note-outline" });
   215→        else if (album)    fields.push({ label: "Album", value: album, icon: "disc-outline" });
   216→        else if (playlist) fields.push({ label: "Playlist", value: playlist, icon: "musical-notes-outline" });
   217→        else if (artist)   fields.push({ label: "Artist", value: artist, icon: "person-outline" });
   218→        break;
   219→      }
   220→      case "linkedin": {
   221→        const m = content.match(/linkedin\.com\/(?:in|company|school)\/([^/?#\s]+)/);
   222→        if (m?.[1]) fields.push({ label: "Profile", value: m[1], icon: "person-outline" });
   223→        break;
   224→      }
   225→      case "telegram": {
   226→        const m = content.match(/t\.me\/([^/?#\s]+)/);
   227→        if (m?.[1]) fields.push({ label: "Username", value: `@${m[1]}`, icon: "paper-plane-outline" });
   228→        break;
   229→      }
   230→      case "discord": {
   231→        const m = content.match(/discord\.(?:gg|com\/invite)\/([^/?#\s]+)/);
   232→        if (m?.[1]) fields.push({ label: "Invite", value: m[1], icon: "link-outline" });
   233→        break;
   234→      }
   235→      case "facebook": {
   236→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   237→        const path = u.pathname.replace(/^\/|\/$/g, "");
   238→        if (path && !["pages", "groups", "events", "login"].includes(path.split("/")[0]))
   239→          fields.push({ label: "Page", value: path, icon: "person-outline" });
   240→        break;
   241→      }
   242→      case "paypal": {
   243→        const username = content.match(/paypal\.me\/([^/?#\s/]+)/)?.[1];
   244→        const amount   = content.match(/paypal\.me\/[^/]+\/([^/?#\s]+)/)?.[1];
   245→        if (username) fields.push({ label: "Username", value: username, icon: "person-outline" });
   246→        if (amount)   fields.push({ label: "Amount", value: amount, icon: "cash-outline" });
   247→        break;
   248→      }
   249→      case "venmo": {
   250→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   251→        const username = u.pathname.replace(/^\/@?|\/$/g, "") || u.searchParams.get("user") || "";
   252→        const amount   = u.searchParams.get("amount") ?? "";
   253→        const note     = u.searchParams.get("note") ?? "";
   254→        if (username) fields.push({ label: "Username", value: `@${username}`, icon: "person-outline" });
   255→        if (amount)   fields.push({ label: "Amount", value: amount, icon: "cash-outline" });
   256→        if (note)     fields.push({ label: "Note", value: note, icon: "document-text-outline" });
   257→        break;
   258→      }
   259→      case "zoom": {
   260→        const meetingId = content.includes("zoom.us/j/") ? content.split("/j/")[1]?.split("?")[0] ?? "" : "";
   261→        let pwd = "";
   262→        try { pwd = new URL(content).searchParams.get("pwd") ?? ""; } catch {}
   263→        if (meetingId) fields.push({ label: "Meeting ID", value: meetingId, icon: "videocam-outline" });
   264→        if (pwd)       fields.push({ label: "Passcode", value: pwd, icon: "key-outline" });
   265→        break;
   266→      }
   267→      case "calendly": {
   268→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   269→        const parts = u.pathname.replace(/^\/|\/$/g, "").split("/").filter(Boolean);
   270→        if (parts[0]) fields.push({ label: "Username", value: parts[0], icon: "person-outline" });
   271→        if (parts[1]) fields.push({ label: "Event", value: parts[1].replace(/-/g, " "), icon: "calendar-outline" });
   272→        break;
   273→      }
   274→      case "razorpay":
   275→      case "donation":
   276→      case "reviewpage":
   277→      case "menucatalogue": {
   278→        try {
   279→          const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   280→          fields.push({ label: "Link", value: u.hostname.replace(/^www\./, "") + u.pathname.replace(/\/$/, ""), icon: "link-outline" });
   281→        } catch {}
   282→        break;
   283→      }
   284→      default:
   285→        break;
   286→    }
   287→  } catch {}
   288→  return fields;
   289→}
   290→
   291→interface Props {
   292→  content: string;
   293→  contentType: string;
   294→  parsedPayment: ParsedPaymentQr | null;
   295→  isDeactivated: boolean;
   296→  onOpenContent: () => void;
   297→  hideOpenAction?: boolean;
   298→  templateKey?: string;
   299→}
   300→
   301→const EXPAND_THRESHOLD = 120;
   302→
   303→const ContentCard = React.memo(function ContentCard({ content, contentType, parsedPayment, isDeactivated, onOpenContent, hideOpenAction, templateKey }: Props) {
   304→  const { colors, isDark } = useTheme();
   305→  const [copied, setCopied] = React.useState(false);
   306→  const [contentExpanded, setContentExpanded] = React.useState(false);
   307→
   308→  const isLongContent = content.length > EXPAND_THRESHOLD || content.includes("\n");
   309→
   310→  // effectiveType: use templateKey whenever it carries a specific type (not a
   311→  // generic alias). This ensures structured types (wifi, contact, …) stored only
   312→  // as templateKey are rendered correctly even when contentType is "url"/"text".
   313→  const GENERIC_TYPES = new Set(["url", "text", "biolink"]);
   314→  const rawEffective = (templateKey && !GENERIC_TYPES.has(templateKey)) ? templateKey : contentType;
   315→
   316→  // Types actively supported for rich display. Anything else (old removed social/
   317→  // payment/media types like instagram, twitter, youtube, linkedin, facebook,
   318→  // spotify, discord, tiktok, snapchat, telegram, zoom, paypal, venmo, razorpay,
   319→  // donation, menucatalogue, reviewpage, google_maps, etc.) falls back to "url".
   320→  const ACTIVE_DISPLAY_TYPES = new Set([
   321→    "url", "text", "email", "wifi", "paymentlink", "contact", "mecard",
   322→    "payment", "upi", "scantopay", "phone", "sms", "location", "event",
   323→    "calendar", "whatsapp", "crypto", "encrypted",
   324→  ]);
   325→  const effectiveType = ACTIVE_DISPLAY_TYPES.has(rawEffective) ? rawEffective : "url";
   326→
   327→  const cfg = getQrTypeStyle(effectiveType, templateKey);
   328→  const hasOpenAction = !isDeactivated && !hideOpenAction && effectiveType !== "text" && effectiveType !== "product";
   329→
   330→  async function handleCopy() {
   331→    await Clipboard.setStringAsync(content);
   332→    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
   333→    if (Platform.OS !== "android") {
   334→      setCopied(true);
   335→      setTimeout(() => setCopied(false), 2000);
   336→    }
   337→  }
   338→
   339→  const URL_LIKE_TYPES = new Set(["url", "instagram", "twitter", "youtube", "linkedin", "telegram", "facebook", "spotify", "discord", "tiktok", "zoom", "calendly", "appdownload", "app", "social", "media", "paypal", "venmo", "mobilepay", "reviewpage", "menucatalogue", "donation", "razorpay", "snapchat"]);
   340→  const isUrlLike = URL_LIKE_TYPES.has(effectiveType) || URL_LIKE_TYPES.has(contentType);
   341→
   342→  const wifi = effectiveType === "wifi" ? parseWifi(content) : null;
   343→  const contact = effectiveType === "contact" ? parseContact(content) : null;
   344→  const smsData = effectiveType === "sms" ? parseSms(content) : null;
   345→  const eventData = (effectiveType === "event" || effectiveType === "calendar") ? parseEvent(content) : null;
   346→  const whatsappData = effectiveType === "whatsapp" ? parseWhatsApp(content) : null;
   347→  const emailData = effectiveType === "email" ? parseEmail(content) : null;
   348→  const phoneStr = effectiveType === "phone" ? parsePhone(content) : null;
   349→  const locationData = effectiveType === "location" ? parseLocation(content) : null;
   350→  const cryptoData = effectiveType === "crypto" ? parseCrypto(content) : null;
   351→  const eventOver = eventData ? isEventPast(eventData.dtend, eventData.dtstart) : false;
   352→
   353→  const smartActionLabel = React.useMemo((): string => {
   354→    if ((effectiveType === "contact" || effectiveType === "mecard") && contact) {
   355→      if (contact.phone) return "Call Now";
   356→      if (contact.email) return "Send Email";
   357→    }
   358→    return cfg.openLabel;
   359→  }, [effectiveType, contact, cfg.openLabel]);
   360→
   361→  const smartActionIcon = React.useMemo((): keyof typeof Ionicons.glyphMap => {
   362→    if ((effectiveType === "contact" || effectiveType === "mecard") && contact) {
   363→      if (contact.phone) return "call-outline";
   364→      if (contact.email) return "mail-outline";
   365→    }
   366→    return "open-outline";
   367→  }, [effectiveType, contact]);
   368→  const isPaymentType = effectiveType === "payment" || effectiveType === "upi" || effectiveType === "scantopay" || effectiveType === "paymentlink";
   369→  const basicPayment = (isPaymentType && !parsedPayment) ? extractBasicPaymentInfo(content) : null;
   370→  const isEmvContent = content.startsWith("000201") || content.startsWith("00020");
   371→
   372→  if (effectiveType === "encrypted") {
   373→    const preview = content.length > 40 ? content.slice(0, 40) + "…" : content;
   374→    const isBase64 = /^[A-Za-z0-9+/]{20,}={0,2}$/.test(content.trim());
   375→    const isHex = /^[0-9a-fA-F]{40,}$/.test(content.trim());
   376→    const dataHint = isBase64 ? "Base64-encoded" : isHex ? "Hex-encoded" : "Proprietary";
   377→    return (
   378→      <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.warning + "50" }]}>
   379→        <LinearGradient colors={[colors.warning + (isDark ? "20" : "10"), "transparent"]} style={StyleSheet.absoluteFill} />
   380→        {/* Header */}
   381→        <View style={styles.cardHeader}>
   382→          <LinearGradient colors={[colors.warning, colors.warningShade ?? colors.warning]} style={styles.cardIcon} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}>
   383→            <Ionicons name="key-outline" size={22} color="#fff" />
   384→          </LinearGradient>
   385→          <View style={{ flex: 1 }}>
   386→            <Text style={[styles.cardTitle, { color: colors.text }]}>Encrypted Data</Text>
   387→            <Text style={[styles.cardSub, { color: colors.textMuted }]}>{dataHint} · {content.length} chars</Text>
   388→          </View>
   389→          <Pressable onPress={handleCopy} style={({ pressed }) => [styles.copyBtn, { backgroundColor: copied ? colors.safe + "18" : isDark ? colors.surfaceLight : colors.background, borderColor: copied ? colors.safe : colors.surfaceBorder, opacity: pressed ? 0.75 : 1 }]}>
   390→            <Ionicons name={copied ? "checkmark-circle" : "copy-outline"} size={14} color={copied ? colors.safe : colors.textMuted} />
   391→            <Text style={[styles.copiedText, { color: copied ? colors.safe : colors.textMuted }]}>{copied ? "Copied!" : "Copy"}</Text>
   392→          </Pressable>
   393→        </View>
   394→        <View style={[styles.infoChipRow, { backgroundColor: colors.warning + "12", borderColor: colors.warning + "30" }]}>
   395→          <Ionicons name="information-circle-outline" size={13} color={colors.warning} />
   396→          <Text style={[styles.infoChipText, { color: colors.warning }]}>
   397→            Proprietary or government-issued data — requires issuer's key to decode.
   398→          </Text>
