export interface WifiData {
  ssid: string;
  password: string;
  security: string;
  hidden: boolean;
}

export function parseWifi(content: string): WifiData | null {
  try {
    const ssid = content.match(/S:([^;]*)/)?.[1] ?? "";
    const password = content.match(/P:([^;]*)/)?.[1] ?? "";
    const security = content.match(/T:([^;]*)/)?.[1] ?? "WPA";
    const hidden = content.includes("H:true");
    if (!ssid) return null;
    return { ssid, password, security, hidden };
  } catch { return null; }
}

export interface ContactData {
  name: string;
  phone: string;
  email: string;
  org: string;
  url: string;
  title: string;
  note: string;
}

export function parseContact(content: string): ContactData {
  const r: ContactData = { name: "", phone: "", email: "", org: "", url: "", title: "", note: "" };
  if (content.startsWith("BEGIN:VCARD")) {
    const fn = content.match(/^FN:(.+)$/m)?.[1]?.trim() ?? "";
    if (fn) {
      r.name = fn;
    } else {
      const nField = content.match(/^N:(.+)$/m)?.[1]?.trim() ?? "";
      const [last = "", first = ""] = nField.split(";");
      r.name = [first.trim(), last.trim()].filter(Boolean).join(" ");
    }
    r.phone = (content.match(/^TEL[^:\r\n]*:(.+)$/m)?.[1] ?? "").trim();
    r.email = (content.match(/^EMAIL[^:\r\n]*:(.+)$/m)?.[1] ?? "").trim();
    r.org   = (content.match(/^ORG:(.+)$/m)?.[1] ?? "").trim().split(";")[0].trim();
    r.url   = (content.match(/^URL:(.+)$/m)?.[1] ?? "").trim();
    r.title = (content.match(/^TITLE:(.+)$/m)?.[1] ?? "").trim();
    r.note  = (content.match(/^NOTE:(.+)$/m)?.[1] ?? "").trim().slice(0, 120);
  } else if (content.toLowerCase().startsWith("mecard:")) {
    r.name  = content.match(/N:([^;]+)/)?.[1]?.trim() ?? "";
    r.phone = content.match(/TEL:([^;]+)/)?.[1]?.trim() ?? "";
    r.email = content.match(/EMAIL:([^;]+)/)?.[1]?.trim() ?? "";
  }
  return r;
}

export interface SmsData { to: string; body: string; }
export interface WhatsAppData { phone: string; text: string; }
export interface EmailData { email: string; subject: string; body: string; }

export function parseSms(content: string): SmsData {
  const smsto = content.match(/^SMSTO:([^:]*):?(.*)?$/i);
  if (smsto) return { to: smsto[1]?.trim() ?? "", body: smsto[2]?.trim() ?? "" };
  try {
    const url = new URL(content);
    const to = url.pathname.replace(/^\//, "");
    const body = url.searchParams.get("body") ?? "";
    return { to, body };
  } catch { return { to: content.replace(/^sms[to]*:/i, "").split("?")[0], body: "" }; }
}

export function parseWhatsApp(content: string): WhatsAppData {
  try {
    const u = new URL(content.startsWith("http") ? content : `https://${content}`);
    const phone = u.pathname.replace(/^\//, "").replace(/\D/g, "");
    const text = u.searchParams.get("text") ?? "";
    return { phone: phone ? "+" + phone : content, text };
  } catch { return { phone: content, text: "" }; }
}

export function parseEmail(content: string): EmailData {
  try {
    const bare = content.replace(/^mailto:/i, "");
    const [addr, qs = ""] = bare.split("?");
    const p = new URLSearchParams(qs);
    return { email: addr || "", subject: p.get("subject") ?? "", body: p.get("body") ?? "" };
  } catch { return { email: content, subject: "", body: "" }; }
}

export function parsePhone(content: string): string {
  return content.replace(/^(tel:|callto:|facetime:)/i, "").trim();
}

export interface EventData {
  summary: string;
  dtstart: string;
  dtend: string;
  location: string;
  description: string;
}

export function parseEvent(content: string): EventData {
  return {
    summary:     content.match(/SUMMARY:([^\r\n]+)/)?.[1] ?? "",
    dtstart:     content.match(/DTSTART[^:]*:([^\r\n]+)/)?.[1] ?? "",
    dtend:       content.match(/DTEND[^:]*:([^\r\n]+)/)?.[1] ?? "",
    location:    content.match(/LOCATION:([^\r\n]+)/)?.[1] ?? "",
    description: content.match(/DESCRIPTION:([^\r\n]+)/)?.[1] ?? "",
  };
}

function icalToDate(dt: string): Date | null {
  if (!dt) return null;
  try {
    const y  = dt.slice(0, 4), mo = dt.slice(4, 6), d = dt.slice(6, 8);
    const h  = dt.slice(9, 11) || "00", mi = dt.slice(11, 13) || "00";
    return new Date(`${y}-${mo}-${d}T${h}:${mi}:00`);
  } catch { return null; }
}

export function formatEventDate(dt: string): string {
  if (!dt) return "";
  const date = icalToDate(dt);
  if (!date) return dt;
  return date.toLocaleDateString(undefined, { weekday: "long", year: "numeric", month: "long", day: "numeric" });
}

export function formatEventTime(dt: string): string {
  if (!dt) return "";
  const date = icalToDate(dt);
  if (!date) return "";
  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
}

export function isEventPast(dtend: string, dtstart: string): boolean {
  const ref = dtend || dtstart;
  if (!ref) return false;
  const date = icalToDate(ref);
  return date ? date < new Date() : false;
}

export interface LocationData { lat: string; lon: string; label: string; }

export function parseLocation(content: string): LocationData {
  const lower = content.toLowerCase();
  if (lower.startsWith("geo:")) {
    const afterGeo = content.slice(4);
    const [coordsPart, queryPart = ""] = afterGeo.split("?");
    const [lat = "", lon = ""] = coordsPart.split(",");
    const label = new URLSearchParams(queryPart).get("q") || "";
    return { lat: lat.trim(), lon: lon.trim(), label: label ? decodeURIComponent(label) : "" };
  }
  if (lower.includes("maps.google.com") || lower.includes("goo.gl/maps")) {
    try {
      const u = new URL(content);
      const q = u.searchParams.get("q") || "";
      return { lat: "", lon: "", label: q ? decodeURIComponent(q) : content };
    } catch {}
  }
  return { lat: "", lon: "", label: content };
}

export interface CryptoData { coin: string; address: string; amount: string; }

export function parseCrypto(content: string): CryptoData {
  const m = content.match(/^(bitcoin|ethereum|litecoin|solana):([^?]+)(\?(.*))?$/i);
  if (m) {
    const coin = m[1].charAt(0).toUpperCase() + m[1].slice(1);
    const address = m[2].trim();
    const amount = new URLSearchParams(m[4] || "").get("amount") || "";
    return { coin, address, amount };
  }
  return { coin: "", address: content, amount: "" };
}

export interface UrlDisplayField {
  label: string;
  value: string;
  icon: string;
}

export interface WebsiteData {
  protocol: string;
  isSecure: boolean;
  hostname: string;
  path: string;
  hasQuery: boolean;
  queryCount: number;
  fullUrl: string;
}

export function parseWebsite(content: string): WebsiteData | null {
  try {
    const withScheme = content.startsWith("http") ? content : `https://${content}`;
    const u = new URL(withScheme);
    const isPrivate = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(u.hostname);
    const isGuard = u.pathname.startsWith("/guard/") || u.pathname.startsWith("/go/");
    if (isPrivate || isGuard) return null;
    const params = [...u.searchParams];
    return {
      protocol:   u.protocol.replace(":", "").toUpperCase(),
      isSecure:   u.protocol === "https:",
      hostname:   u.hostname.replace(/^www\./, ""),
      path:       u.pathname !== "/" ? u.pathname : "",
      hasQuery:   params.length > 0,
      queryCount: params.length,
      fullUrl:    content.startsWith("http") ? content : `https://${content}`,
    };
  } catch { return null; }
}

export function extractSocialFields(contentType: string, content: string): UrlDisplayField[] {
  const fields: UrlDisplayField[] = [];
  try {
    switch (contentType) {
      case "instagram": {
        const m = content.match(/instagram\.com\/([^/?#\s]+)/);
        if (m?.[1] && m[1] !== "p" && m[1] !== "reel")
          fields.push({ label: "Profile", value: `@${m[1]}`, icon: "person-outline" });
        break;
      }
      case "twitter": {
        const m = content.match(/(?:twitter|x)\.com\/([^/?#\s]+)/);
        if (m?.[1] && !["i", "intent", "home", "explore"].includes(m[1]))
          fields.push({ label: "Username", value: `@${m[1]}`, icon: "person-outline" });
        break;
      }
      case "tiktok": {
        const m = content.match(/tiktok\.com\/@([^/?#\s]+)/);
        if (m?.[1]) fields.push({ label: "Username", value: `@${m[1]}`, icon: "person-outline" });
        break;
      }
      case "snapchat": {
        const m = content.match(/snapchat\.com\/add\/([^/?#\s]+)/);
        if (m?.[1]) fields.push({ label: "Username", value: m[1], icon: "person-outline" });
        break;
      }
      case "youtube": {
        const channel = content.match(/youtube\.com\/@([^/?#\s]+)/)?.[1]
          ?? content.match(/youtube\.com\/channel\/([^/?#\s]+)/)?.[1]
          ?? content.match(/youtube\.com\/c\/([^/?#\s]+)/)?.[1];
        const video = content.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([^&/?#\s]+)/)?.[1];
        if (channel) fields.push({ label: "Channel", value: `@${channel}`, icon: "play-circle-outline" });
        if (video)   fields.push({ label: "Video ID", value: video, icon: "play-outline" });
        break;
      }
      case "spotify": {
        const track    = content.match(/spotify\.com\/track\/([^/?#\s]+)/)?.[1];
        const album    = content.match(/spotify\.com\/album\/([^/?#\s]+)/)?.[1];
        const playlist = content.match(/spotify\.com\/playlist\/([^/?#\s]+)/)?.[1];
        const artist   = content.match(/spotify\.com\/artist\/([^/?#\s]+)/)?.[1];
        if (track)         fields.push({ label: "Track", value: track, icon: "musical-note-outline" });
        else if (album)    fields.push({ label: "Album", value: album, icon: "disc-outline" });
        else if (playlist) fields.push({ label: "Playlist", value: playlist, icon: "musical-notes-outline" });
        else if (artist)   fields.push({ label: "Artist", value: artist, icon: "person-outline" });
        break;
      }
      case "linkedin": {
        const m = content.match(/linkedin\.com\/(?:in|company|school)\/([^/?#\s]+)/);
        if (m?.[1]) fields.push({ label: "Profile", value: m[1], icon: "person-outline" });
        break;
      }
      case "telegram": {
        const m = content.match(/t\.me\/([^/?#\s]+)/);
        if (m?.[1]) fields.push({ label: "Username", value: `@${m[1]}`, icon: "paper-plane-outline" });
        break;
      }
      case "discord": {
        const m = content.match(/discord\.(?:gg|com\/invite)\/([^/?#\s]+)/);
        if (m?.[1]) fields.push({ label: "Invite", value: m[1], icon: "link-outline" });
        break;
      }
      case "facebook": {
        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
        const path = u.pathname.replace(/^\/|\/$/g, "");
        if (path && !["pages", "groups", "events", "login"].includes(path.split("/")[0]))
          fields.push({ label: "Page", value: path, icon: "person-outline" });
        break;
      }
      case "paypal": {
        const username = content.match(/paypal\.me\/([^/?#\s/]+)/)?.[1];
        const amount   = content.match(/paypal\.me\/[^/]+\/([^/?#\s]+)/)?.[1];
        if (username) fields.push({ label: "Username", value: username, icon: "person-outline" });
        if (amount)   fields.push({ label: "Amount", value: amount, icon: "cash-outline" });
        break;
      }
      case "venmo": {
        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
        const username = u.pathname.replace(/^\/@?|\/$/g, "") || u.searchParams.get("user") || "";
        const amount   = u.searchParams.get("amount") ?? "";
        const note     = u.searchParams.get("note") ?? "";
        if (username) fields.push({ label: "Username", value: `@${username}`, icon: "person-outline" });
        if (amount)   fields.push({ label: "Amount", value: amount, icon: "cash-outline" });
        if (note)     fields.push({ label: "Note", value: note, icon: "document-text-outline" });
        break;
      }
      case "zoom": {
        const meetingId = content.includes("zoom.us/j/") ? content.split("/j/")[1]?.split("?")[0] ?? "" : "";
        let pwd = "";
        try { pwd = new URL(content).searchParams.get("pwd") ?? ""; } catch {}
        if (meetingId) fields.push({ label: "Meeting ID", value: meetingId, icon: "videocam-outline" });
        if (pwd)       fields.push({ label: "Passcode", value: pwd, icon: "key-outline" });
        break;
      }
      case "calendly": {
        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
        const parts = u.pathname.replace(/^\/|\/$/g, "").split("/").filter(Boolean);
        if (parts[0]) fields.push({ label: "Username", value: parts[0], icon: "person-outline" });
        if (parts[1]) fields.push({ label: "Event", value: parts[1].replace(/-/g, " "), icon: "calendar-outline" });
        break;
      }
      case "razorpay":
      case "donation":
      case "reviewpage":
      case "menucatalogue": {
        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
        fields.push({ label: "Link", value: u.hostname.replace(/^www\./, "") + u.pathname.replace(/\/$/, ""), icon: "link-outline" });
        break;
      }
      case "appdownload":
      case "app": {
        const isApple = content.includes("apps.apple.com");
        fields.push({ label: "Store", value: isApple ? "App Store" : "Google Play", icon: "download-outline" });
        try {
          const u = new URL(content.startsWith("http") ? content : `https://${content}`);
          const appName = u.pathname.split("/").filter(Boolean).pop()?.replace(/-/g, " ") || "";
          if (appName) fields.push({ label: "App", value: appName, icon: "apps-outline" });
        } catch {}
        break;
      }
      default:
        break;
    }
  } catch {}
  return fields;
}

export function extractBasicPaymentInfo(content: string) {
  try {
    return {
      vpa:      content.match(/pa=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/pa=([^&\s]+)/i)![1]) : undefined,
      name:     content.match(/pn=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/pn=([^&\s]+)/i)![1]) : undefined,
      amount:   content.match(/(?:\bam|amount)=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/(?:\bam|amount)=([^&\s]+)/i)![1]) : undefined,
      currency: content.match(/cu=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/cu=([^&\s]+)/i)![1]) : undefined,
    };
  } catch { return {}; }
}

