import React from "react";
import { View, Text, StyleSheet } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useTheme } from "@/contexts/ThemeContext";
import { CardHeader, InfoGrid, InfoRow, Divider, OpenButton } from "../shared";
import { extractSocialFields } from "../parsers";
import { getQrTypeStyle } from "@/lib/config/qr-type-styles";

interface Props {
  content: string;
  contentType: string;
  onOpenContent: () => void;
  isDeactivated: boolean;
  hideOpenAction?: boolean;
}

export default function SocialCard({ content, contentType, onOpenContent, isDeactivated, hideOpenAction }: Props) {
  const { colors, isDark } = useTheme();
  const cfg = getQrTypeStyle(contentType);
  const accentColor = cfg.gradient[0];

  const fields = extractSocialFields(contentType, content);

  const displaySubtitle = cfg.extractDisplayValue
    ? cfg.extractDisplayValue(content)
    : (() => {
        try {
          return new URL(content.startsWith("http") ? content : `https://${content}`).hostname.replace(/^www\./, "");
        } catch { return undefined; }
      })();

  return (
    <View style={[styles.card, { backgroundColor: colors.surface, borderColor: accentColor + "45" }]}>
      <LinearGradient
        colors={[accentColor + (isDark ? "18" : "0C"), "transparent"]}
        style={StyleSheet.absoluteFill}
      />
      <CardHeader
        icon={cfg.icon as keyof typeof Ionicons.glyphMap}
        gradient={cfg.gradient}
        title={cfg.label}
        subtitle={displaySubtitle || undefined}
        content={content}
        colors={colors}
      />

      {fields.length > 0 && (
        <InfoGrid accentColor={accentColor} colors={colors} isDark={isDark}>
          {fields.map((f, i) => (
            <React.Fragment key={f.label}>
              {i > 0 && <Divider colors={colors} />}
              <InfoRow
                label={f.label}
                value={f.value}
                icon={f.icon as keyof typeof Ionicons.glyphMap}
                accentColor={accentColor}
                colors={colors}
                selectable
              />
            </React.Fragment>
          ))}
        </InfoGrid>
      )}

      {/* Full URL box for transparency */}
      <View style={[styles.urlBox, { backgroundColor: isDark ? colors.surfaceLight : colors.background, borderColor: colors.surfaceBorder }]}>
        <Text style={[styles.urlLabel, { color: colors.textMuted }]}>Link</Text>
        <Text style={[styles.urlText, { color: colors.text }]} selectable numberOfLines={2}>
          {content}
        </Text>
      </View>

      {!isDeactivated && !hideOpenAction && (
        <OpenButton label={cfg.openLabel} gradient={cfg.gradient} onPress={onOpenContent} />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  card:     { borderRadius: 20, padding: 16, marginBottom: 12, borderWidth: 1, overflow: "hidden", gap: 12 },
  urlBox:   { borderRadius: 12, padding: 12, borderWidth: 1, gap: 4 },
  urlLabel: { fontSize: 10, fontFamily: "Inter_600SemiBold", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 2 },
  urlText:  { fontSize: 13, fontFamily: "Inter_400Regular", lineHeight: 20, letterSpacing: 0.1 },
});

export { default as WebsiteCard } from "./WebsiteCard";
export { default as WifiCard } from "./WifiCard";
export { default as ContactCard } from "./ContactCard";
export { default as EmailCard } from "./EmailCard";
export { default as SmsCard } from "./SmsCard";
export { default as WhatsAppCard } from "./WhatsAppCard";
export { default as PhoneCard } from "./PhoneCard";
export { default as LocationCard } from "./LocationCard";
export { default as CryptoCard } from "./CryptoCard";
export { default as EventCard } from "./EventCard";
export { default as EncryptedCard } from "./EncryptedCard";
export { default as TextCard } from "./TextCard";
export { default as SocialCard } from "./SocialCard";

/**
 * ContentCard — main orchestrator
 *
 * Resolves the effective QR type and renders the correct per-type card.
 * All parsing lives in ./parsers/, all card UI in ./cards/, shared atoms in ./shared/.
 *
 * To add a new type:
 *  1. Add a parser in ./parsers/ and export it from ./parsers/index.ts
 *  2. Create a card in ./cards/ and export it from ./cards/index.ts
 *  3. Add the type key to ACTIVE_TYPES below and wire it in the switch.
 */

import React from "react";
import type { ParsedPaymentQr } from "@/lib/qr-analysis";
import PaymentCard from "@/features/qr-detail/components/PaymentCard";
import { View } from "react-native";
import {
  WebsiteCard,
  WifiCard,
  ContactCard,
  EmailCard,
  SmsCard,
  WhatsAppCard,
  PhoneCard,
  LocationCard,
  CryptoCard,
  EventCard,
  EncryptedCard,
  TextCard,
  SocialCard,
} from "./cards";
import { extractBasicPaymentInfo } from "./parsers";

// ── Type sets ─────────────────────────────────────────────────────────────────

const GENERIC_TYPES = new Set(["url", "text", "biolink"]);

/** All types that have a dedicated rich card — anything else renders as WebsiteCard */
const ACTIVE_TYPES = new Set([
  // Structured / non-URL
  "text", "email", "wifi", "contact", "mecard",
  "payment", "upi", "scantopay", "paymentlink",
  "phone", "sms", "location", "event", "calendar",
  "whatsapp", "crypto", "encrypted",
  // Social & URL-based (now fully supported)
  "url", "instagram", "twitter", "youtube", "linkedin",
  "telegram", "facebook", "spotify", "discord", "tiktok",
  "snapchat", "zoom", "calendly", "paypal", "venmo",
  "reviewpage", "menucatalogue", "donation", "razorpay",
  "appdownload", "app", "google_maps",
]);

/** Types that render via SocialCard (URL-based with platform branding) */
const SOCIAL_TYPES = new Set([
  "instagram", "twitter", "youtube", "linkedin", "telegram",
  "facebook", "spotify", "discord", "tiktok", "snapchat",
  "zoom", "calendly", "paypal", "venmo",
  "reviewpage", "menucatalogue", "donation", "razorpay",
  "appdownload", "app", "google_maps",
]);

// ── Props ─────────────────────────────────────────────────────────────────────

interface Props {
  content: string;
  contentType: string;
  parsedPayment: ParsedPaymentQr | null;
  isDeactivated: boolean;
  onOpenContent: () => void;
  hideOpenAction?: boolean;
  templateKey?: string;
}

// ── Component ─────────────────────────────────────────────────────────────────

const ContentCard = React.memo(function ContentCard({
  content,
  contentType,
  parsedPayment,
  isDeactivated,
  onOpenContent,
  hideOpenAction,
  templateKey,
}: Props) {
  // Resolve the effective type: templateKey wins unless it's a generic alias
  const rawEffective = (templateKey && !GENERIC_TYPES.has(templateKey))
    ? templateKey
    : contentType;
  const effectiveType = ACTIVE_TYPES.has(rawEffective) ? rawEffective : "url";

  // ── Payment ────────────────────────────────────────────────────────────────
  if (
    effectiveType === "payment" ||
    effectiveType === "upi" ||
    effectiveType === "scantopay" ||
    effectiveType === "paymentlink"
  ) {
    const isEmv = content.startsWith("000201") || content.startsWith("00020");
    const basic = !parsedPayment ? extractBasicPaymentInfo(content) : null;
    const paymentData: ParsedPaymentQr = parsedPayment ?? (isEmv
      ? {
          app: "emv_generic", appDisplayName: "Bank Merchant QR", appCategory: "emv",
          region: "Regional", recipientId: "", rawContent: content, isAmountPreFilled: false,
        }
      : {
          app: "upi", appDisplayName: "UPI Payment", appCategory: "upi_india", region: "India",
          recipientId: basic?.vpa || "", recipientName: basic?.name,
          amount: basic?.amount, currency: basic?.currency || "INR",
          rawContent: content, isAmountPreFilled: !!basic?.amount, vpa: basic?.vpa,
        });
    return (
      <View>
        <PaymentCard
          parsedPayment={paymentData}
          isDeactivated={isDeactivated}
          onOpenContent={onOpenContent}
        />
      </View>
    );
  }

  // ── Encrypted ─────────────────────────────────────────────────────────────
  if (effectiveType === "encrypted") {
    return <EncryptedCard content={content} />;
  }

  // ── Structured protocol types ──────────────────────────────────────────────
  const commonProps = { content, onOpenContent, isDeactivated, hideOpenAction };

  switch (effectiveType) {
    case "wifi":     return <WifiCard     {...commonProps} />;
    case "contact":
    case "mecard":   return <ContactCard  {...commonProps} />;
    case "email":    return <EmailCard    {...commonProps} />;
    case "sms":      return <SmsCard      {...commonProps} />;
    case "whatsapp": return <WhatsAppCard {...commonProps} />;
    case "phone":    return <PhoneCard    {...commonProps} />;
    case "location":
    case "google_maps":
                     return <LocationCard {...commonProps} />;
    case "crypto":   return <CryptoCard   {...commonProps} />;
    case "event":
    case "calendar": return <EventCard    {...commonProps} />;
    case "text":     return <TextCard content={content} />;
  }

  // ── Social / platform URL types ────────────────────────────────────────────
  if (SOCIAL_TYPES.has(effectiveType)) {
    return (
      <SocialCard
        content={content}
        contentType={effectiveType}
        onOpenContent={onOpenContent}
        isDeactivated={isDeactivated}
        hideOpenAction={hideOpenAction}
      />
    );
  }

  // ── Generic website URL (default) ──────────────────────────────────────────
  return (
    <WebsiteCard
      content={content}
      onOpenContent={onOpenContent}
      isDeactivated={isDeactivated}
      hideOpenAction={hideOpenAction}
    />
  );
});

export default ContentCard;

