    16→async function recordViewedLocally(
    17→  qrCodeId: string,
    18→  content: string,
    19→  contentType: string,
    20→  userId: string
    21→): Promise<void> {
    22→  try {
    23→    const key = `local_scan_history_${userId}`;
    24→    const stored = await AsyncStorage.getItem(key);
    25→    const arr: any[] = stored ? JSON.parse(stored) : [];
    26→    const alreadyExists = arr.some((e) => e.qrCodeId === qrCodeId);
    27→    if (alreadyExists) return;
    28→    arr.unshift({
    29→      id: `viewed_${qrCodeId}_${Date.now()}`,
    30→      qrCodeId,
    31→      content,
    32→      contentType,
    33→      scanSource: "viewed",
    34→      scannedAt: new Date().toISOString(),
    35→    });
    36→    await AsyncStorage.setItem(key, JSON.stringify(arr));
    37→  } catch {}
    38→}
    39→
    40→async function loadOfflineFallback(id: string): Promise<{ content: string; contentType: string } | null> {
    41→  const inMem = getAnonymousQrContent(id);
    42→  if (inMem) return { content: inMem.content, contentType: inMem.contentType || "text" };
    43→  try {
    44→    const raw = await AsyncStorage.getItem(`qr_content_${id}`);
    45→    if (raw) {
    46→      const { content, contentType } = JSON.parse(raw);
    47→      return { content, contentType: contentType || "text" };
    48→    }
    49→  } catch {}
    50→  return null;
    51→}
    52→
    53→type QrFetchResult =
    54→  | { status: "data"; detail: any; isFreshFetch: boolean }
    55→  | { status: "offline"; content: string; contentType: string }
    56→  | { status: "error" };
    57→
    58→async function fetchQrData(id: string, userId: string | null): Promise<QrFetchResult> {
    59→  const cached = await getCachedQrDetail<any>(id, userId);
    60→  if (cached) return { status: "data", detail: cached, isFreshFetch: false };
    61→
    62→  let lastErr: any = null;
    63→  for (let attempt = 0; attempt < 3; attempt++) {
    64→    try {
    65→      if (attempt > 0) await new Promise((r) => setTimeout(r, attempt * 1500));
    66→      const detail = await loadQrDetail(id, userId);
    67→      if (!detail) {
    68→        if (attempt < 2) { lastErr = new Error("not_found"); continue; }
    69→        const offline = await loadOfflineFallback(id);
    70→        if (offline) return { status: "offline", ...offline };
    71→        return { status: "error" };
    72→      }
    73→      AsyncStorage.setItem(`qr_content_${id}`, JSON.stringify({
    74→        content: detail.qrCode.content,
    75→        contentType: detail.qrCode.contentType,
    76→      })).catch(() => {});
    77→      return { status: "data", detail, isFreshFetch: true };
    78→    } catch (err: any) {
    79→      console.warn(`[qrData] Firestore fetch attempt ${attempt + 1}/3 failed: code=${err?.code} message=${err?.message}`);
    80→      lastErr = err;
    81→    }
    82→  }
    83→
    84→  const trulyOffline =
    85→    lastErr?.code === "unavailable" ||
    86→    (typeof navigator !== "undefined" && !navigator.onLine) ||
    87→    /network|offline|failed to fetch/i.test(lastErr?.message || "");
    88→  const offline = await loadOfflineFallback(id);
    89→  if (offline && (trulyOffline || offline)) return { status: "offline", ...offline };
    90→  return { status: "error" };
    91→}
