   123→    staleTime: 5 * 60 * 1000,
   124→    gcTime: 30 * 60 * 1000,
   125→    refetchOnWindowFocus: false,
   126→    retry: false,
   127→  });
   128→
   129→  const loading = isPending;
   130→  const offlineMode = result?.status === "offline";
   131→  const loadError = result?.status === "error" || isError;
   132→  const qrCode: QrDetail | null = result?.status === "data" ? result.detail.qrCode : null;
   133→  const offlineContent = result?.status === "offline" ? result.content : null;
   134→  const offlineContentType = result?.status === "offline" ? result.contentType : "text";
   135→
