   130→    const parsedAmount = amount ? parseFloat(amount) : 0;
   131→    if (parsedAmount > 0) url += `&am=${parsedAmount.toFixed(2)}`;
   132→    // cu=INR always present — some UPI apps reject links without it
   133→    url += `&cu=${currency || "INR"}`;
