     1→// ─── QR Content Type Classifier ──────────────────────────────────────────────
     2→// Detects 20+ content types across every country and platform worldwide.
     3→// Single responsibility: takes raw QR string → returns a content type string.
     4→// No database access, no side-effects.
     5→
     6→import { isPaymentQr } from "../qr-analysis";
     7→
     8→export function detectContentType(content: string): string {
     9→  if (!content) return "text";
    10→  const t = content.trim();
    11→  const lower = t.toLowerCase();
    12→
    13→  // ── 1. PAYMENT — highest priority (UPI, all apps, crypto, EMV, SEPA, Pix…) ──
    14→  if (isPaymentQr(t)) return "payment";
    15→
    16→  // ── 2. STANDARD QR SCHEMES ──
    17→  if (lower.startsWith("tel:") || lower.startsWith("callto:") || lower.startsWith("facetime:")) return "phone";
    18→  if (lower.startsWith("mailto:") || lower.startsWith("matmsg:")) return "email";
    19→  if (t.startsWith("WIFI:") || lower.startsWith("wifi:")) return "wifi";
    20→  if (lower.startsWith("geo:") || lower.startsWith("maps:") || lower.startsWith("comgooglemaps://")) return "location";
    21→  if (lower.startsWith("sms:") || lower.startsWith("smsto:") || lower.startsWith("mms:") || lower.startsWith("mmsto:")) return "sms";
    22→  if (lower.startsWith("otpauth://")) return "otp";
    23→
    24→  // App store deep links
    25→  if (
    26→    lower.startsWith("market://") || lower.startsWith("itms://") ||
    27→    lower.startsWith("itms-appss://") || lower.startsWith("itms-apps://") ||
    28→    lower.startsWith("appgallery://")
    29→  ) return "app";
    30→
    31→  // ── 3. STANDARD TEXT FORMAT TYPES ──
    32→  if (t.startsWith("BEGIN:VCARD") || lower.startsWith("mecard:") || lower.startsWith("mebkm:")) return "contact";
    33→  if (t.startsWith("BEGIN:VCALENDAR") || t.startsWith("BEGIN:VEVENT")) return "event";
    34→
    35→  // ── 4. SPECIAL DOCUMENT FORMATS ──
    36→  if (/^M\d[A-Z ]{2,}/.test(t) && t.length > 40) return "boarding";
    37→  if (/^\d{13}$/.test(t) || /^97[89]\d{10}$/.test(t)) return "product";
    38→  if (/^\+?[\d\s\-().]{7,16}$/.test(t) && /\d{6,}/.test(t)) return "phone";
    39→  if (/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(lower)) return "email";
